def to_tensor_type(self, x):
        if isinstance(x, tl.dtype):
            return x
        elif isinstance(x, tl.constexpr_type):
            x = x.value

        if isinstance(x, bool):
            return tl.int1
        elif isinstance(x, int):
            if -2**31 <= x < 2**31:
                return tl.int32
            elif 2**31 <= x < 2**32:
                return tl.uint32
            elif -2**63 <= x < 2**63:
                return tl.int64
            elif 2**63 <= x < 2**64:
                return tl.uint64
            raise ValueError(f'Nonrepresentable integer {x}.')
